using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using OrcaFacil.Application.Abstractions; using OrcaFacil.Application.Documents; using OrcaFacil.Application.DTOs; using OrcaFacil.Domain.Enums;
namespace OrcaFacil.Web.Pages.Documents; [Authorize] public class CreateBudgetModel:PageModel{private readonly ICurrentUserService _current; private readonly DocumentService _service; public CreateBudgetModel(ICurrentUserService current,DocumentService service){_current=current;_service=service;} [BindProperty] public DocumentForm Input{get;set;}=DocumentForm.Default(); public async Task<IActionResult> OnPostAsync(CancellationToken ct){if(!ModelState.IsValid)return Page(); var cmd=new CreateDocumentCommand(_current.UserId,DocumentType.Budget,"",Input.ClientName,Input.ToItems(),Input.Discount,Input.Notes); var r=await _service.CreateBudgetAsync(cmd,ct); if(!r.Succeeded){ModelState.AddModelError("",r.Error??"Erro ao criar orçamento.");return Page();} return RedirectToPage("/Documents/Details",new{id=r.Value});}}
public class DocumentForm{public string ClientName{get;set;}=""; public decimal Discount{get;set;} public string? Notes{get;set;} public List<DocumentItemForm> Items{get;set;}=[]; public static DocumentForm Default()=>new(){Items=[new()]}; public IReadOnlyList<DocumentItemDto> ToItems()=>Items.Where(i=>!string.IsNullOrWhiteSpace(i.Description)).Select(i=>new DocumentItemDto(i.Description,i.Quantity,i.UnitPrice,i.Discount)).ToList();}
public class DocumentItemForm{public string Description{get;set;}=""; public decimal Quantity{get;set;}=1; public decimal UnitPrice{get;set;} public decimal Discount{get;set;}}
